      "id": "repertoire.machine_exercises",
      "tiers": [
        {
          "id": "repertoire.machine_exercises:t1",
          "title": "Железо, будем знакомы",
          "phrase": "У тебя в атласе 2 разных упражнения на тренажёре. Робот-смотритель расставляет первые экспонаты — железо обживается.",
          "imagePrompt": "A small square-headed robot with clamp hands places a lat pulldown bar and a braided cable rope in an open display cabinet, leaning back proudly while the rope curls over the shelf edge like a curious tail.",
          "fishMarkup": "[warm]У тебя в атласе 2 разных упражнения на тренажёре. [playful]Робот-смотритель расставляет первые экспонаты — железо обживается.",
          "audioText": "У тебя в атласе 2 разных упражнения на тренажёре. Робот-смотритель расставляет первые экспонаты — железо обживается."
        },
        {
          "id": "repertoire.machine_exercises:t2",
          "title": "Бюро железных знакомств",
          "phrase": "Теперь в твоём атласе 5 разных упражнений на тренажёре. Робот-смотритель просит железо не толпиться у витрины.",
          "imagePrompt": "The square-headed robot extends its display cabinet into a fan of five shelves, sorting a pulldown bar, cable rope, V-handle, ankle cuff and single grip; two attachments crowd one shelf as its clamp ushers them apart.",
          "fishMarkup": "[confident]Теперь в твоём атласе 5 разных упражнений на тренажёре. [playful]Робот-смотритель просит железо не толпиться у витрины.",
          "audioText": "Теперь в твоём атласе 5 разных упражнений на тренажёре. Робот-смотритель просит железо не толпиться у витрины."
        },
        {
          "id": "repertoire.machine_exercises:t3",
          "title": "Билет в собственный музей",
          "phrase": "В твоём атласе уже 10 разных упражнений на тренажёре. Робот-смотритель открыл целый музей — и сам купил билет.",
          "imagePrompt": "The square-headed robot feeds a blank ticket into the entrance turnstile of its own miniature exercise museum; ten distinct machine attachments fill curved display racks behind it, while its free clamp points proudly back at itself.",
          "fishMarkup": "[triumphant]В твоём атласе уже 10 разных упражнений на тренажёре. [playful]Робот-смотритель открыл целый музей — <slow>и сам купил билет.</slow>",
          "audioText": "В твоём атласе уже 10 разных упражнений на тренажёре. Робот-смотритель открыл целый музей — и сам купил билет."
        }
      ]
    },
    {
      "id": "repertoire.timed_exercises",
      "tiers": [
        {
          "id": "repertoire.timed_exercises:t1",
          "title": "Знакомство с песком",
          "phrase": "Ты знаешь уже 2 разных упражнения на время и растяжку. Песочные часы шуршат: «Приятно познакомиться!»",
          "imagePrompt": "A squat hourglass with mitten hands and short feet stands beside a half-unrolled exercise mat, offering a neatly looped stretching strap with one hand and a shy little greeting with the other.",
          "fishMarkup": "[warm]Ты знаешь уже 2 разных упражнения на время и растяжку. [playful]Песочные часы шуршат: «Приятно познакомиться!»",
          "audioText": "Ты знаешь уже 2 разных упражнения на время и растяжку. Песочные часы шуршат: «Приятно познакомиться!»"
        },
        {
          "id": "repertoire.timed_exercises:t2",
          "title": "У времени есть варианты",
          "phrase": "В твоём репертуаре 5 разных упражнений на время и растяжку. Песочные часы развернули коврик-гармошку: вариантов хватает!",
          "imagePrompt": "The squat hourglass with mitten hands pulls open an accordion-fold exercise mat with five broad panels; a stretching strap loops loosely over one arm, while its short feet brace against the comically expanding mat.",
          "fishMarkup": "[confident]В твоём репертуаре 5 разных упражнений на время и растяжку. [playful]Песочные часы развернули коврик-гармошку: вариантов хватает!",
          "audioText": "В твоём репертуаре 5 разных упражнений на время и растяжку. Песочные часы развернули коврик-гармошку: вариантов хватает!"
        },
        {
          "id": "repertoire.timed_exercises:t3",
          "title": "Будильник за первой партой",
          "phrase": "В твоём атласе уже 10 разных упражнений на время и растяжку. Песочные часы открыли школу терпения — будильник сел за первую парту.",
          "imagePrompt": "The squat hourglass with mitten hands teaches a tiny classroom of alarm clocks seated at desks made from rolled exercise mats; the front clock eagerly raises a bell like a hand, while the hourglass calmly rests its hands together.",
          "fishMarkup": "[triumphant]В твоём атласе уже 10 разных упражнений на время и растяжку. [playful]Песочные часы открыли школу терпения — <slow>будильник сел за первую парту.</slow>",
          "audioText": "В твоём атласе уже 10 разных упражнений на время и растяжку. Песочные часы открыли школу терпения — будильник сел за первую парту."
        }
      ]
    }
  ]
}
